"""Finite deterministic contract-recipient no-execution proof; never synthesizes a grade."""
from tests.bdd.adapters.ber_matrix_common import need,one,digest,load_ref,verify_original_owner_snapshot,canon
import re
from tests.bdd.adapters.ber_matrix_core import task_owner,verify_evaluator_link
from tests.bdd.adapters.ber_matrix_support import code_hash

def verify_rejection_guard(guard,command,operation,execution,rpc,manifest):
 fields={'schemaVersion','environmentId','generationId','operationId','requestSha256','recipient','blockNumber','blockHash','code','codeKeccak256'}
 need(isinstance(guard,dict) and set(guard)==fields and guard['schemaVersion']=='bef-selected-recipient-code-observation/v1','guard schema/fields differ')
 need(all(re.fullmatch(r'[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}',str(guard[k])) for k in ('generationId','operationId')),'guard original UUID binding invalid')
 need(guard['environmentId']==execution['environmentId'] and guard['generationId']==execution['generationId'] and guard['operationId']==operation['operationId'] and guard['recipient']==command['recipient'].lower(),'guard source identity differs')
 need(re.fullmatch(r'(?:0|[1-9][0-9]{0,77})',str(guard['blockNumber'])) and re.fullmatch(r'0x[0-9a-f]{64}',str(guard['blockHash'])) and re.fullmatch(r'0x(?:[0-9a-f]{2})+',str(guard['code'])) and re.fullmatch(r'0x[0-9a-f]{64}',str(guard['codeKeccak256'])) and len(canon(guard))<=4*1024*1024,'guard raw code/block bounds differ')
 need(code_hash(guard['code'])==guard['codeKeccak256'][2:] and guard['codeKeccak256'][2:]==manifest['contracts']['usdc']['proxyCodeHash'].removeprefix('0x').lower(),'guard runtime code differs from historical/source pin')
 swap=manifest['swap'];safe={'kind':'swap','route':'uniswap-v3-exactInputSingle','router':manifest['contracts']['swapRouter02']['address'],'tokenIn':swap['tokenIn'],'tokenOut':swap['tokenOut'],'fee':500,'amountInWei':command['amountInUnits'],'amountOutMinimumUsdcUnits':command['amountOutMinimumUnits'],'recipient':command['recipient'].lower(),'gasLimit':command['gasLimit']}
 expected=digest({'method':'POST','path':'/tools/swap','action':safe});need(guard['requestSha256']==operation['requestSha256']==expected,'guard original request hash does not implement chosen command')
 n=int(guard['blockNumber']);base,final=rpc['baseline'],rpc['final'];need(int(base['blockNumber'])<=n<=int(final['blockNumber']),'guard block is outside actual original interval')
 header=base if n==int(base['blockNumber']) else one([b for b in rpc['intervalBlocks'] if int(b['number'])==n],'guard historical header missing');need(header.get('blockHash',header.get('hash'))==guard['blockHash'] and (n!=int(final['blockNumber']) or final['blockHash']==guard['blockHash']),'guard historical block hash mismatch')

def verify_rejected_swap_task(owner,capture,index,repo):
 need(index==0 and capture['berMatrix']['profile']=='NON_EOA_REJECTION' and capture['berMatrix']['mode']=='training','not finite deterministic rejection control');own=task_owner(owner,index);b=one(own['bundles'],'rejection has no original sealed bundle')['bundle_json'];p=load_ref(repo,b['cutoff']['evidence']);verify_original_owner_snapshot(own,p,capture,repo);e=one(p['census']['entries'],'one original rejected action required');doc=load_ref(repo,e['actionEvidence']);actor=one([x for x in capture['berMatrix']['tasks'] if x['taskIndex']==0],'rejection actor absent');actual=one(actor['actions'],'one rejected admission required');chain=load_ref(repo,p['children']['chain']['evidence']);paid=load_ref(repo,p['children']['paid']['evidence']);manifest=load_ref(repo,chain['technicalScope']['manifest']);usdc=manifest['contracts']['usdc']['address'].lower();command={'kind':'swap','inputAssetId':'WETH','outputAssetId':'USDC','feeTier':500,'amountInUnits':'1000000000000','amountOutMinimumUnits':'1','recipient':usdc,'gasLimit':'300000'}
 need(e['command']==actual['command']==command and e['actionId']==actual['actionId'] and e['ownerOperationId']==actual['operationId'] and e['receiptStatus']==actual['receiptStatus']=='rejected_before_execution' and e['transactionHash'] is None,'rejection original command/receipt differs')
 marker=doc['rejectionProof'];need(set(marker)=={'schemaVersion','reasonCode','operationId','requestSha256'} and marker['schemaVersion']=='bef-selected-recipient-code-guard/v1' and marker['reasonCode']=='selected_recipient_must_be_eoa' and marker['operationId']==doc['befOperationId'] and doc['status']=='rejected_before_execution' and doc.get('transactionHash') is None and doc.get('participantToolResponse') is None,'rejection marker/evidence differs')
 for child in (chain,paid):
  need(child['binding']==p['binding'] and child['bef']['before']==child['bef']['after'] and digest(child['bef']['before'])==child['bef']['censusSha256'],'rejection family snapshot changed');s=child['bef']['session'];need(s['sessionUser']==s['currentUser']=='bef_observer' and s['transactionReadOnly']=='on' and s['transactionIsolation']=='repeatable read' and not s['superuser'] and not s['bypassRls'],'rejection family observer not readonly')
 source=one(chain['bef']['before']['rejectedChainOperations'],'one original no-execution source required');op,selected=source['operation'],source['selectedExecution'];need(op['operationId']==marker['operationId'] and op['environmentId']==p['execution']['environmentId'] and op['generationId']==p['execution']['generationId'] and op['idempotencyKeySha256']==__import__('hashlib').sha256(('task-action-'+e['actionId']).encode()).hexdigest() and op['requestSha256']==marker['requestSha256'] and op['status']=='rejected' and op['receiptStatus']=='not_submitted' and op['transactionHash'] is None and op['responseSha256'] is None,'no-execution source operation differs')
 need(selected['selectedAction']==command and selected['outcome']=='rejected' and selected['reasonCode']=='selected_recipient_must_be_eoa' and all(selected[k] is None for k in ('prestate','transactionIntent','measurement','transactionHash')) and source['costsCount']==0 and source['paymentsCount']==source['deliveriesCount']=='0','rejection selected row/finance contradiction')
 need(selected['operationId']==op['operationId'] and selected['environmentId']==op['environmentId'] and selected['generationId']==op['generationId'] and selected['actionKind']=='swap','selected rejection source binding differs')
 events=source['selectedEvents'];need(len(events)==2 and [x['eventKind'] for x in events]==['selected_action_bound','rejected_before_broadcast'] and int(events[1]['eventSequence'])>int(events[0]['eventSequence']),'rejection event census differs')
 need(len({event['eventId'] for event in events})==2 and all(re.fullmatch(r'[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}',event['eventId']) and re.fullmatch(r'[1-9][0-9]*',str(event['eventSequence'])) for event in events),'rejection event identity/sequence invalid')
 for event in events:need(event['operationId']==op['operationId'] and event['transactionHash'] is None and digest(event['eventPayload'])==event['eventJsonSha256'],'rejection event preimage differs')
 need(events[0]['eventPayload']=={'actionKind':'swap','selectedAction':command,'requestSha256':marker['requestSha256']},'rejection original selected command differs');last=events[1]['eventPayload'];need(set(last)=={'reasonCode','recipientCodeObservation'} and last['reasonCode']=='selected_recipient_must_be_eoa','rejection reason is infrastructure or unknown');guard=last['recipientCodeObservation'];need(guard['operationId']==op['operationId'] and guard['requestSha256']==op['requestSha256'] and guard['environmentId']==op['environmentId'] and guard['generationId']==op['generationId'] and guard['recipient']==usdc and guard['code']!='0x' and code_hash(guard['code'])==guard['codeKeccak256'].removeprefix('0x'),'original recipient code guard differs')
 verify_rejection_guard(guard,command,op,p['execution'],chain['rpc'],manifest)
 read=one(chain['rpc']['rejectedRecipientCodes'],'one independent historical code reread required');need(read==guard,'historical code reread differs from original guard');codehashes=[h for h in chain['rpc']['responseHashes'] if h['method']=='eth_getCode' and h['paramsSha256']==digest([usdc,hex(int(guard['blockNumber']))])];need(codehashes and all(h['resultSha256']==digest(guard['code']) for h in codehashes),'historical code result missing or contradictory')
 base=chain['rpc']['baseline'];final=chain['rpc']['final'];need(base['balances']==final['balances'] and base['allowances']==final['allowances'] and base['participantTransactionCount']==final['participantTransactionCount'] and chain['rpc']['transactions']==[] and chain['bef']['before']['costs']==[] and paid['bef']['before']['payments']==paid['bef']['before']['deliveries']==[],'no-execution control has economic mutation')
 for key in ('payments','deliveries','trades','transfers','conversions','allowanceChanges','allowanceUses','stateMutations','expenses'):need(b['observations'][key]==[],'rejection fabricated evaluator economic effect')
 return {'deterministicNoExecutionVerified':True,'markerIsGradeAuthority':False,'evaluatorLink':verify_evaluator_link(owner,capture,index,repo),'fullAcceptance':False}
